import React from 'react';

interface InlineInputProps {
  id?: string;
  value: number | string;
  onCommit: (val: number) => void;
  unit?: string;
  fill?: string;
  fontFamily?: string;
  fontSize?: string;
  textAnchor?: "middle" | "start" | "end" | "inherit";
  x?: string | number;
  y?: string | number;
  fontWeight?: string;
  step?: number | string;
}

const InlineInput: React.FC<InlineInputProps> = ({
  id, value, onCommit, unit = "", fill,
  fontFamily = "Helvetica", fontSize = "11px", textAnchor = "middle",
  x, y, fontWeight, step = "any"
}) => {
  const [isEditing, setIsEditing] = React.useState(false);
  const [tempVal, setTempVal] = React.useState(String(value));

  React.useEffect(() => {
      if (!isEditing) setTempVal(String(value));
  }, [value, isEditing]);

  const handleBlur = () => {
      setIsEditing(false);
      const parsed = parseFloat(tempVal);
      if (!isNaN(parsed)) {
          onCommit(parsed);
      }
    };
    
    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          handleBlur();
      } else if (e.key === 'Escape') {
          setIsEditing(false);
          setTempVal(String(value));
      }
  };

    if (isEditing) {
        const width = 85;
        const height = 20;
        const fx = x ? Number(x) - width / 2 : -width / 2;
        const fy = y ? Number(y) - height / 2 : -height / 2;
        return (
            <foreignObject x={fx} y={fy} width={width} height={height} onClick={(e) => e.stopPropagation()}>
                <input
                    type="number"
                    step={step}
                    value={tempVal}
                    onChange={(e) => {
                        const val = e.target.value;
                        setTempVal(val);
                        const parsed = parseFloat(val);
                        if (!isNaN(parsed)) {
                            onCommit(parsed);
                        }
                    }}
                    onBlur={handleBlur}
                    onKeyDown={handleKeyDown}
                    autoFocus
                    style={{
                        width: '100%',
                        height: '100%',
                        background: '#1a202c',
                        border: '1px solid ' + (fill || 'currentColor'),
                        color: fill || 'currentColor',
                        fontFamily: fontFamily,
                        fontSize: fontSize,
                        fontWeight: fontWeight || 'normal',
                        textAlign: 'center',
                        paddingLeft: '14px',
                        borderRadius: '3px',
                        outline: 'none',
                        margin: '0',
                        boxSizing: 'border-box'
                    }}
                />
            </foreignObject>
        );
    }

    return (
        <text
            id={id}
            x={x}
            y={y}
            fill={fill}
            fontFamily={fontFamily}
            fontSize={fontSize}
            textAnchor={textAnchor}
            className="editable-label"
            style={{ fontWeight: fontWeight, pointerEvents: 'all', cursor: 'pointer' }}
            onClick={(e) => {
                e.stopPropagation();
                setIsEditing(true);
            }}
        >
            {value}{unit ? " " + unit : ""}
        </text>
    );
};

